    throw std::runtime_error("Failed to compute priority");
    return 42;
}

// A function that takes a shared_ptr and another value
void processWidget(std::shared_ptr<Widget> spw, int priority) {
    // ... process the widget
}

void run() {
    try {
        // POTENTIAL LEAK: If computePriority() throws, the Widget allocated
        // by 'new' is leaked because the shared_ptr constructor hasn't run yet.
        // The evaluation order could be: 1. new Widget, 2. computePriority(), 3. shared_ptr constructor.
        // processWidget(std::shared_ptr<Widget>(new Widget()), computePriority());

        // SAFE: make_shared encapsulates allocation and construction. 
        // The function call is atomic from the caller's perspective. No leak is possible.
        processWidget(std::make_shared<Widget>(), computePriority());

    } catch (const std::exception& e) {
        // With make_shared, no Widget is leaked if an exception is caught.
    }
}
